#[derive(Resource)] struct Game{entry:PathBuf,inventory:Option<forge_engine::Inventory>,inventory_open:bool,inventory_selected:Option<usize>,inventory_message:String,project:Project,sim:Simulation,original:Project,demo:Option<forge_engine::DemoSession>,root:PathBuf,level:usize,menu:bool,campaign:bool,finished:bool,#[cfg(feature="audio")] audio_revision:u64}
#[cfg(feature="audio")] #[derive(Component)] struct AudioBus {shared:Option<String>,members:Vec<uuid::Uuid>,gain:f32,music:bool,source:uuid::Uuid,spatial:bool,distance:f32,last_volume:f32}
