fn main(){if std::env::args().nth(1).as_deref()==Some("--benchmark"){let path=std::env::args_os().nth(2).map(PathBuf::from).unwrap_or_else(||PathBuf::from("examples/signal_lost/project.forge.json"));match forge_engine::performance::benchmark(&path,600){Ok(report)=>{println!("{report}");return;},Err(e)=>{eprintln!("{e}");std::process::exit(1);}}}if std::env::args().nth(1).as_deref()==Some("--smoke"){let path=std::env::args_os().nth(2).map(PathBuf::from).unwrap_or_else(||PathBuf::from("examples/signal_lost/project.forge.json"));match Project::load(&path).and_then(|p|{forge_engine::modules::validate(&p)?;forge_engine::smoke(p)}){Ok(())=>{println!("SMOKE PASS");return;},Err(e)=>{eprintln!("SMOKE FAIL: {e}");std::process::exit(1);}}}let path=std::env::args_os().nth(1).map(PathBuf::from).unwrap_or_else(||PathBuf::from("project.forge.json"));let path=match path.canonicalize(){Ok(p)=>p,Err(e)=>{eprintln!("Project: {e}");std::process::exit(1);}};let p=match Project::load(&path){Ok(p)=>p,Err(e)=>{eprintln!("{e}");std::process::exit(1);}};if let Err(e)=forge_engine::modules::validate(&p){eprintln!("{e}");std::process::exit(1); }let folder=path.parent().unwrap().to_path_buf();let root=folder.to_string_lossy().into_owned();let campaign=folder.join("level2.forge.json").is_file() && folder.join("level3.forge.json").is_file() && path.file_name().is_some_and(|n|n=="project.forge.json");let mut app=App::new();app.insert_resource(Game{entry:path.clone(),inventory:p.settings.inventory.clone(),inventory_open:false,inventory_selected:None,inventory_message:String::new(),project:p.clone(),sim:Simulation::default(),original:p.clone(),demo:(forge_engine::DemoSession::total(&p)>0).then(forge_engine::DemoSession::default),root:folder,level:1,menu:forge_engine::DemoSession::total(&p)>0,campaign,finished:false,#[cfg(feature="audio")] audio_revision:0}).add_plugins(DefaultPlugins.set(AssetPlugin{file_path:root,..default()}).set(ImagePlugin::default_nearest()).set(WindowPlugin{primary_window:Some(Window{title:p.name.clone(),resolution:(p.settings.production.resolution[0] as f32,p.settings.production.resolution[1] as f32).into(),..default()}),..default()})).add_plugins(EguiPlugin::default()).init_resource::<HudInput>().add_systems(EguiPrimaryContextPass,hud).add_systems(Startup,setup).add_systems(Update,(tick,particle_render).chain());#[cfg(feature="audio")] { use bevy::audio::AddAudioSource; app.add_audio_source::<audio_dsp::DspAudio>().add_systems(Update,(sync_scene_audio,mix_audio).chain().after(tick)); }#[cfg(feature="lighting")] app.add_plugins((forge_engine::gpu_scene::GpuScenePlugin,forge_engine::gpu_particles::GpuParticlesPlugin)).add_systems(PostUpdate,(gpu_scene_sync,gpu_particles_sync).chain().before(bevy::transform::TransformSystem::TransformPropagate));if std::env::var_os("FORGE_GPU_PROFILE").is_some(){app.add_plugins((bevy::render::diagnostic::RenderDiagnosticsPlugin,bevy::diagnostic::LogDiagnosticsPlugin::default()));}app.run();}
fn setup(mut commands:Commands,game:Res<Game>,assets:Res<AssetServer>){commands.spawn(Camera2d);#[cfg(feature="audio")] commands.spawn((bevy::audio::SpatialListener::new(32.),Transform::default()));for o in &game.project.objects{if o.camera{continue;}let mut sprite=Sprite::from_color(Color::srgba_u8(o.color[0],o.color[1],o.color[2],o.color[3]),Vec2::from_array(o.size));if let Some(path)=&o.sprite{sprite.image=assets.load(path.clone());}commands.spawn((sprite,Transform::default(),ObjectId(o.id)));}}
/// A scene transition or explicit restart starts the scene's audio once, including one-shots.
#[cfg(feature="audio")]
fn sync_scene_audio(mut commands:Commands,game:Res<Game>,assets:Res<AssetServer>,voices:Query<Entity,With<AudioBus>>,mut revision:Local<Option<u64>>,mut dsp_assets:ResMut<Assets<audio_dsp::DspAudio>>){
 if *revision==Some(game.audio_revision){return;} *revision=Some(game.audio_revision);
 for entity in &voices{commands.entity(entity).despawn();}
 let mut dsp_budget=32*1024*1024usize;let mut dsp_count=0usize;
 let mut grouped=std::collections::HashSet::new();
 // Only explicit top-level cascade roots; failures keep legacy direct bus/source paths.
 for (name,definition) in &game.project.settings.audio_buses{if !definition.cascade_runtime||!forge_engine::BUILTIN_AUDIO_BUSES.contains(&definition.parent.as_str())||dsp_count>=16{continue;}
 let members:Vec<_>=game.project.objects.iter().filter_map(|o|o.pro.sound.as_ref().filter(|s|s.custom_bus.as_deref().is_some_and(|route|game.project.settings.cascade_root_contains(name,route))).map(|s|(o.id,s))).collect();if !(2..=16).contains(&members.len()){continue;}let sounds:Vec<_>=members.iter().map(|(_,s)|*s).collect();match audio_dsp::DspAudio::load_cascade(&game.root,&sounds,&game.project.settings,name,dsp_budget){Ok((source,bytes,cascade))=>{dsp_budget=dsp_budget.saturating_sub(bytes);dsp_count+=1;grouped.extend(members.iter().map(|(id,_)|*id));let volume=(game.project.settings.custom_bus_gain(&definition.parent).unwrap_or(0.)*game.project.settings.master).clamp(0.,1.);let settings=if sounds[0].looping{PlaybackSettings::ONCE}else{PlaybackSettings::DESPAWN};let gains=source.gains();let meter=source.meter();let bus=AudioBus{shared:Some(name.clone()),members:members.iter().map(|(id,_)|*id).collect(),gain:1.,music:false,source:members[0].0,spatial:false,distance:1.,last_volume:-1.};commands.spawn((AudioPlayer(dsp_assets.add(source)),Transform::default(),settings.with_volume(bevy::audio::Volume::Linear(volume)),bus,gains,cascade,meter));},Err(err)=>eprintln!("Cascade {name} fallback: {err}")}}

 for (name,definition) in &game.project.settings.audio_buses{if !definition.summed_runtime||dsp_count>=16{continue;}
  let members:Vec<_>=game.project.objects.iter().filter_map(|o|o.pro.sound.as_ref().filter(|s|!grouped.contains(&o.id)&&s.custom_bus.as_deref()==Some(name.as_str())).map(|s|(o.id,s))).collect();
  if members.len()<2{continue;}let sounds:Vec<_>=members.iter().map(|(_,s)|*s).collect();let fx=game.project.settings.summed_bus_effects(name);
  match audio_dsp::DspAudio::load_summed(&game.root,&sounds,fx,dsp_budget){Ok((source,bytes))=>{
   dsp_budget=dsp_budget.saturating_sub(bytes);dsp_count+=1;grouped.extend(members.iter().map(|(id,_)|*id));let volume=(game.project.settings.custom_bus_gain(name).unwrap_or(0.)*game.project.settings.master).clamp(0.,1.);let control=source.control();let settings=if sounds[0].looping{PlaybackSettings::ONCE}else{PlaybackSettings::DESPAWN};let settings=settings.with_volume(bevy::audio::Volume::Linear(volume));
   let gains=source.gains();let meter=source.meter();let bus=AudioBus{shared:Some(name.clone()),members:members.iter().map(|(id,_)|*id).collect(),gain:1.,music:false,source:members[0].0,spatial:false,distance:1.,last_volume:-1.};commands.spawn((AudioPlayer(dsp_assets.add(source)),Transform::default(),settings,bus,control,gains,meter));eprintln!("Live shared bus: {name} ({} sources)",members.len());
  },Err(err)=>eprintln!("Shared bus {name} fallback: {err}")}
 }
 for o in &game.project.objects{if let Some(s)=&o.pro.sound{if grouped.contains(&o.id){continue;}if !forge_engine::valid_asset(&s.path){continue;}let bus=s.gain(&game.project.settings);let volume=(s.volume*bus*game.project.settings.master).clamp(0.,1.);let settings=if s.looping{PlaybackSettings::LOOP}else{PlaybackSettings::DESPAWN};let settings=settings.with_spatial(s.stereo_pan&&s.route()!=forge_engine::AudioRoute::Music).with_spatial_scale(bevy::audio::SpatialScale::new_2d(0.01));let transform=Transform::from_xyz(o.position[0],o.position[1],0.);let settings=settings.with_volume(bevy::audio::Volume::Linear(volume)).with_speed(s.speed.clamp(0.5,2.));let bus=AudioBus{shared:None,members:Vec::new(),gain:s.volume,music:s.route()==forge_engine::AudioRoute::Music,source:o.id,spatial:s.spatial,distance:s.distance,last_volume:-1.};if let Some(fx)=s.effective_effects(&game.project.settings){if dsp_count<16{match audio_dsp::DspAudio::load(&game.root,&s.path,fx,dsp_budget,s.looping){Ok((source,bytes))=>{dsp_budget=dsp_budget.saturating_sub(bytes);dsp_count+=1;let control=source.control();let settings=if s.looping{PlaybackSettings::ONCE.with_spatial(s.stereo_pan&&s.route()!=forge_engine::AudioRoute::Music).with_spatial_scale(bevy::audio::SpatialScale::new_2d(0.01)).with_volume(bevy::audio::Volume::Linear(volume)).with_speed(s.speed.clamp(0.5,2.))}else{settings};commands.spawn((AudioPlayer(dsp_assets.add(source)),transform,settings,bus,control));continue;},Err(err)=>eprintln!("DSP fallback for {}: {err}",s.path)}}}commands.spawn((AudioPlayer::new(assets.load::<AudioSource>(s.path.clone())),transform,settings,bus));}}
}
fn tick(mut commands:Commands,assets:Res<AssetServer>,time:Res<Time>,keys:Res<ButtonInput<KeyCode>>,pads:Query<&Gamepad>,hud:Res<HudInput>,mut game:ResMut<Game>,images:Res<Assets<Image>>,mut sprites:Query<(Entity,&ObjectId,&mut Transform,&mut Sprite),Without<Camera2d>>,mut cameras:Query<&mut Transform,With<Camera2d>>){let c=&game.project.settings.production.controls;let pressed=|s:&str,k|keys.pressed(forge_engine::keycode(s,k)) as i32;let mut d=[(pressed(&c.right,KeyCode::KeyD)-pressed(&c.left,KeyCode::KeyA)) as f32,(pressed(&c.up,KeyCode::KeyW)-pressed(&c.down,KeyCode::KeyS)) as f32];for pad in &pads{let dz=c.deadzone.clamp(0.,0.95);let axis=|a|{let v=pad.get(a).unwrap_or(0.);if v.abs()>dz{v}else{0.}};d[0]+=axis(GamepadAxis::LeftStickX);d[1]+=axis(GamepadAxis::LeftStickY);if pad.pressed(GamepadButton::South){d[1]=1.;}}for i in 0..2{d[i]=(d[i]+hud.0[i]).clamp(-1.,1.);}let g=&mut *game;if keys.just_pressed(KeyCode::F5){g.inventory_message=match save_checkpoint(g){Ok(())=>"Checkpoint saved".into(),Err(e)=>e};}if keys.just_pressed(KeyCode::F9){g.inventory_message=match load_checkpoint(g){Ok(())=>"Checkpoint loaded".into(),Err(e)=>e};}if g.inventory.is_some()&&keys.just_pressed(KeyCode::KeyI){g.inventory_open=!g.inventory_open;}if !g.menu&&keys.just_pressed(KeyCode::KeyE){if let Some(inv)=g.inventory.as_mut(){g.inventory_message=match inv.collect_nearby(&mut g.project){Ok(s)|Err(s)=>s};}}if g.inventory_open{d=[0.;2];}if g.demo.is_none()&&keys.just_pressed(KeyCode::Escape){g.menu=!g.menu;}if g.demo.is_some(){
 if keys.just_pressed(KeyCode::Escape){g.menu=!g.menu;}
 if hud.1 || keys.just_pressed(KeyCode::KeyR){g.project=g.original.clone();if let Some(inv)=&g.inventory{inv.remove_collected(&mut g.project);}#[cfg(feature="audio")] {g.audio_revision=g.audio_revision.wrapping_add(1);}g.sim=Simulation::default();g.demo=Some(forge_engine::DemoSession::default());g.menu=false;g.finished=false;}
 if keys.just_pressed(KeyCode::Enter){g.menu=false;}
 if (hud.2 || keys.just_pressed(KeyCode::KeyN)) && g.demo.as_ref().is_some_and(|d|d.won){if g.campaign && g.level<4 && g.root.join(format!("level{}.forge.json",g.level+1)).is_file() {let next=g.level+1;match Project::load(&g.root.join(format!("level{next}.forge.json"))){Ok(p)=>{if let Err(e)=forge_engine::modules::validate(&p){eprintln!("{e}");return;}g.level=next;g.original=p.clone();g.project=p;if let Some(inv)=&g.inventory{inv.remove_collected(&mut g.project);}#[cfg(feature="audio")] {g.audio_revision=g.audio_revision.wrapping_add(1);}g.sim=Simulation::default();g.demo=Some(forge_engine::DemoSession::default());g.menu=false;},Err(e)=>eprintln!("Level load: {e}")}}else{g.finished=true;}}
 }
 if !g.menu && !g.finished && !g.demo.as_ref().is_some_and(|x|x.won||x.health==0){let dt=time.delta_secs().min(0.033);g.sim.step(&mut g.project,dt,d);if g.demo.is_none()&&keys.just_pressed(KeyCode::KeyJ){if let Some(id)=g.project.objects.iter().find(|o|o.player).map(|o|o.id){let bonus=g.inventory.as_ref().map(|i|i.damage_bonus(&g.project.settings.item_catalog)).unwrap_or(0.);forge_engine::combat::strike_with_bonus(&mut g.project,id,if d[0]<0.{-1.}else{1.},bonus);}}if let Some(demo)=&mut g.demo{#[cfg(feature="audio")] let old=(demo.score(),demo.health,demo.won);demo.face(d[0]);if keys.just_pressed(KeyCode::KeyJ){demo.attack(&mut g.project);}demo.step(&mut g.project,dt);#[cfg(feature="audio")] let cue=if demo.won&&!old.2{Some("win")}else if demo.health<old.1{Some("hurt")}else if demo.score()>old.0{Some("collect")}else{None};#[cfg(feature="audio")] if let Some(cue)=cue{let path=format!("assets/{cue}.wav");if g.root.join(&path).is_file(){commands.spawn((AudioPlayer::new(assets.load::<AudioSource>(path)),PlaybackSettings::DESPAWN.with_volume(bevy::audio::Volume::Linear((g.project.settings.master*g.project.settings.sfx).clamp(0.,1.)))));}}}}
 let objects:std::collections::HashMap<_,_>=g.project.objects.iter().filter(|o|!o.camera).map(|o|(o.id,o)).collect();let existing:std::collections::HashSet<_>=sprites.iter().map(|(_,id,_,_)|id.0).collect();
 for (entity,id,_,_) in &mut sprites{if !objects.contains_key(&id.0){commands.entity(entity).despawn();}}
 for o in &g.project.objects{if !o.camera&&!existing.contains(&o.id){let mut s=Sprite::from_color(Color::WHITE,Vec2::from_array(o.size));if let Some(path)=&o.sprite{s.image=assets.load(path.clone());}commands.spawn((s,Transform::default(),ObjectId(o.id)));}}for (_,id,mut t,mut s) in &mut sprites{if let Some(o)=objects.get(&id.0).copied(){let (frame_center,frame_size)=forge_engine::sprite_frame_geometry(o,g.project.isometric,forge_engine::animation_time(o,g.sim.elapsed));s.custom_size=Some(Vec2::from_array(frame_size));let desired:Handle<Image>=o.sprite.as_ref().map(|path|assets.load(path.clone())).unwrap_or_default();if s.image!=desired{s.image=desired;s.rect=None;}let c=forge_engine::lit_color(o,&g.project);s.color=Color::srgba_u8(c[0],c[1],c[2],forge_engine::sprite_visual_alpha(o,forge_engine::animation_time(o,g.sim.elapsed),c[3]));let p=forge_engine::sprite_center(o,g.project.isometric);t.translation=Vec3::new(frame_center[0],frame_center[1],o.layer as f32*10.+if g.project.isometric{-p[1]*0.001}else{0.});t.rotation=Quat::from_rotation_z(o.rotation.to_radians());if o.sprite.is_some(){if let Some(img)=images.get(&s.image){let uv=o.animation.uv(forge_engine::animation_time(o,g.sim.elapsed));let size=img.size().as_vec2();s.rect=Some(Rect::from_corners(Vec2::from_array(uv[0])*size,Vec2::from_array(uv[2])*size));}}}}if let Some(o)=g.project.objects.iter().find(|o|o.camera){let p=project_point(o.position,g.project.isometric);for mut t in &mut cameras{t.translation.x=p[0];t.translation.y=p[1];}}}

#[derive(Component)] struct ParticleVisual;
fn particle_render(mut commands:Commands,game:Res<Game>,assets:Res<AssetServer>,mut old:Query<(Entity,&mut Sprite,&mut Transform),With<ParticleVisual>>){let mut pool=old.iter_mut();let mut count=0;#[cfg(feature="lighting")] let gpu=forge_engine::gpu_particles::selected(&game.project);for o in &game.project.objects{#[cfg(feature="lighting")] if gpu.contains(&o.id){continue;}for (p,size,c) in forge_engine::particles(o,game.sim.elapsed){if count>=4096{break;}count+=1;let p=project_point(p,game.project.isometric);let mut sprite=Sprite::from_color(Color::srgba_u8(c[0],c[1],c[2],c[3]),Vec2::splat(size));if let Some(path)=&o.production.particle_texture{if path.starts_with("assets/"){sprite.image=assets.load(path.clone());}}let t=Transform::from_xyz(p[0],p[1],o.layer as f32*10.+1.);if let Some((_,mut s,mut tr))=pool.next(){*s=sprite;*tr=t;}else{commands.spawn((ParticleVisual,sprite,t));}}}for (e,_,_) in pool{commands.entity(e).despawn();}}

fn hud(mut contexts:EguiContexts,game:ResMut<Game>,mut input:ResMut<HudInput>,#[cfg(feature="audio")] meters:Query<(&AudioBus,&audio_dsp::PeakMeter)>){let mut game=game;let mut toggle_pause=false;input.0=[0.;2];input.1=false;input.2=false;let Ok(ctx)=contexts.ctx_mut()else{return;};if let Some(d)=&game.demo{egui::Area::new(egui::Id::new("demo_hud")).fixed_pos(egui::pos2(24.,20.)).show(ctx,|ui|{egui::Frame::window(ui.style()).show(ui,|ui|{ui.heading("FORGE / SIGNAL LOST");ui.label(format!("ENERGY CORES  {} / {}",d.score(),forge_engine::DemoSession::total(&game.project)));ui.label(format!("SECTOR {}  |  HEALTH {} / 3",game.level,d.health));ui.label(if game.finished {"CAMPAIGN COMPLETE"}else if d.won {"SECTOR COMPLETE  |  N to continue"}else if d.health==0{"SIGNAL LOST  |  R to retry"}else{"A / D move · W jump · J attack · Esc menu"});if d.won&&!game.finished && ui.button("Continue").clicked(){input.2=true;}if d.health==0 && ui.button("Retry").clicked(){input.1=true;}});});if game.menu{egui::Window::new("SIGNAL LOST").anchor(egui::Align2::CENTER_CENTER,[0.,0.]).collapsible(false).resizable(false).show(ctx,|ui|{ui.heading("SIGNAL LOST / PRO");ui.label("Recover three energy cores and reach the exit.");if ui.button("Start / Restart sector").clicked(){input.1=true;}ui.label("Enter: resume  |  Esc: menu");});}}#[cfg(feature="audio")] {let id=egui::Id::new("forge_live_mixer");let mut open=ctx.data(|d|d.get_temp::<bool>(id)).unwrap_or(false);if ctx.input(|i|i.key_pressed(egui::Key::F8)){open=!open;}ctx.data_mut(|d|d.insert_temp(id,open));if game.menu||open{egui::Window::new("Audio mixer · F8").show(ctx,|ui|{ui.add(egui::Slider::new(&mut game.project.settings.master,0. ..=1.).text("Master"));ui.add(egui::Slider::new(&mut game.project.settings.music,0. ..=1.).text("Music"));ui.add(egui::Slider::new(&mut game.project.settings.sfx,0. ..=1.).text("SFX"));ui.add(egui::Slider::new(&mut game.project.settings.voice,0. ..=1.).text("Voice"));ui.add(egui::Slider::new(&mut game.project.settings.ambience,0. ..=1.).text("Ambience"));ui.collapsing("Custom buses",|ui|{for (name,b) in &mut game.project.settings.audio_buses{ui.push_id(name,|ui|{ui.add(egui::Slider::new(&mut b.gain,0. ..=1.).text(name.as_str()));ui.checkbox(&mut b.mute,"Mute");if let Some(fx)=&mut b.effects{ui.horizontal_wrapped(|ui|{for (name,preset) in forge_engine::DSP_PRESETS{if ui.small_button(name).clicked(){*fx=preset;}}});ui.add(egui::Slider::new(&mut fx.low_db,-12. ..=12.).text("Bus low EQ"));ui.add(egui::Slider::new(&mut fx.high_db,-12. ..=12.).text("Bus high EQ"));ui.add(egui::Slider::new(&mut fx.room,0. ..=1.).text("Bus room"));ui.add(egui::Slider::new(&mut fx.reverb,0. ..=1.).text("Bus reverb"));}});}});ui.separator();ui.collapsing("Shared bus peaks / limiter",|ui|{for (bus,meter) in &meters{let [pre,post,reduction]=meter.take();ui.label(format!("{} · pre {:.2} · post {:.2} · reduction {:.1}%",bus.shared.as_deref().unwrap_or("DSP"),pre,post,reduction*100.));ui.add(egui::ProgressBar::new(post.clamp(0.,1.)));}ui.small("Sample peaks before external sink/master gain; not true-peak or LUFS. Limiter ceiling 0.98.");});ui.small("Live normalized PCM sources enabled at scene start; F8 toggles mixer");egui::ScrollArea::vertical().max_height(300.).show(ui,|ui|{for o in game.project.objects.iter_mut().filter(|o|o.pro.sound.is_some()).take(128){let s=o.pro.sound.as_mut().unwrap();ui.push_id(o.id,|ui|{ui.collapsing(&o.name,|ui|{ui.add(egui::Slider::new(&mut s.volume,0. ..=1.).text("Gain"));if let Some(fx)=&mut s.effects{ui.add(egui::Slider::new(&mut fx.low_db,-12. ..=12.).text("Low dB"));ui.add(egui::Slider::new(&mut fx.high_db,-12. ..=12.).text("High dB"));ui.add(egui::Slider::new(&mut fx.room,0. ..=1.).text("Room"));ui.add(egui::Slider::new(&mut fx.reverb,0. ..=1.).text("Reverb"));ui.horizontal_wrapped(|ui|{for (name,preset) in forge_engine::DSP_PRESETS{if ui.button(name).clicked(){*fx=preset;}}});}else{ui.small("No local DSP; may inherit bus preset");}});});}});});}}let rect=ctx.screen_rect();for (i,w) in game.project.settings.widgets.iter().enumerate().filter(|(_,w)|game.project.settings.hud_canvas_groups||w.group.trim().is_empty()){let size=forge_engine::adaptive_widget(w,[rect.width(),rect.height()],game.project.settings.production.resolution);let pos=rect.min+egui::vec2(size[0],size[1]);egui::Area::new(egui::Id::new(("hud",i))).fixed_pos(pos).show(ctx,|ui|{if w.action=="label"{if game.project.settings.hud_canvas_groups{ui.add_sized([size[2],size[3]],egui::Label::new(&w.text));}else{ui.label(&w.text);}}else if w.action=="progress"{let value=game.project.objects.iter().find(|o|o.player).and_then(|o|o.pro.variables.get(&w.text)).copied().unwrap_or(0.).clamp(0.,1.);ui.add_sized([size[2],size[3]],egui::ProgressBar::new(value).text(w.text.clone()));}else{let r=ui.add_sized([size[2],size[3]],egui::Button::new(&w.text));if w.action=="pause"&&r.clicked(){toggle_pause=true;}if r.is_pointer_button_down_on(){match w.action.as_str(){"left"=>input.0[0]-=1.,"right"=>input.0[0]+=1.,"jump"=>input.0[1]=1.,_=>{}}}}});}
 if toggle_pause{game.menu=!game.menu;}
 checkpoint_panel(ctx,&mut game);
 inventory_panel(ctx,&mut game);
 if game.project.settings.hud_canvas_groups{return;}
 let mut groups=std::collections::BTreeMap::<String,HudGroup>::new();for w in &game.project.settings.widgets{let parts=w.group.split('/').map(str::trim).filter(|s|!s.is_empty()).take(8).collect::<Vec<_>>();if let Some((root,rest))=parts.split_first(){groups.entry((*root).into()).or_default().insert(rest,w);}}
 for (name,group) in groups{if let Some(first)=group.first(){let size=forge_engine::adaptive_widget(first,[rect.width(),rect.height()],game.project.settings.production.resolution);let pos=rect.min+egui::vec2(size[0],size[1]);egui::Window::new(name.as_str()).id(egui::Id::new(("hud_group",&name))).default_pos(pos).resizable(true).show(ctx,|ui|group.draw(ui,&mut input));}}

}

#[cfg(feature="audio")] fn mix_audio(time:Res<Time>,game:Res<Game>,mut sinks:Query<(&mut AudioBus,Option<&mut bevy::audio::AudioSink>,Option<&mut bevy::audio::SpatialAudioSink>,&mut Transform,Option<&audio_dsp::DspControl>,Option<&audio_dsp::TrackGains>,Option<&audio_dsp::CascadeControl>),Without<bevy::audio::SpatialListener>>,mut ears:Query<&mut Transform,With<bevy::audio::SpatialListener>>,mut source_indices:Local<std::collections::HashMap<uuid::Uuid,usize>>){use bevy::audio::AudioSinkPlayback;if sinks.is_empty(){return;}let listener=game.project.objects.iter().find(|o|o.player).or_else(||game.project.objects.iter().find(|o|o.camera));source_indices.clear();source_indices.extend(game.project.objects.iter().enumerate().map(|(i,o)|(o.id,i)));if let Some(o)=listener{for mut t in &mut ears{t.translation=Vec3::new(o.position[0],o.position[1],0.);}}for (mut bus,mut sink,mut spatial_sink,mut transform,control,gains,cascade) in &mut sinks {if sink.is_none()&&spatial_sink.is_none(){continue;}if let Some(name)=bus.shared.as_deref(){let settings=&game.project.settings;if let Some(c)=cascade{c.update(settings);}if let Some(c)=control{c.set(settings.summed_bus_effects(name));}if let Some(gains)=gains{for (i,id) in bus.members.iter().enumerate(){let gain=source_indices.get(id).and_then(|idx|game.project.objects.get(*idx)).and_then(|o|o.pro.sound.as_ref()).map(|s|s.volume).unwrap_or(0.);gains.set(i,gain);}}let route=if cascade.is_some(){settings.audio_buses.get(name).map(|b|b.parent.as_str()).unwrap_or("")}else{name};let volume=(settings.custom_bus_gain(route).unwrap_or(0.)*settings.master).clamp(0.,1.);let k=1.-(-time.delta_secs().clamp(0.,0.1)*18.).exp();let target=if bus.last_volume<0.||volume==0.{volume}else{let v=bus.last_volume+(volume-bus.last_volume)*k;if (v-volume).abs()<0.002{volume}else{v}};if (target-bus.last_volume).abs()>0.0001{if let Some(s)=sink.as_mut(){s.set_volume(bevy::audio::Volume::Linear(target));}bus.last_volume=target;}continue;}let source=source_indices.get(&bus.source).and_then(|i|game.project.objects.get(*i));let channel=source.and_then(|o|o.pro.sound.as_ref()).map(|s|s.gain(&game.project.settings)).unwrap_or(if bus.music{game.project.settings.music}else{game.project.settings.sfx});if let Some(sound)=source.and_then(|o|o.pro.sound.as_ref()){bus.gain=sound.volume;if let Some(c)=control{c.set(sound.effective_effects(&game.project.settings).unwrap_or_default());}}if let Some(o)=source{transform.translation=Vec3::new(o.position[0],o.position[1],0.);}let attenuation=if bus.spatial&&!bus.music{match (source,listener){(Some(a),Some(b))=>forge_engine::sound_attenuation(a.position,b.position,bus.distance),_=>0.}}else{1.};let volume=(bus.gain*channel*game.project.settings.master*attenuation).clamp(0.,1.);let target=if bus.last_volume<0.||volume==0.{volume}else{let k=1.-(-time.delta_secs().clamp(0.,0.1)*18.).exp();let next=bus.last_volume+(volume-bus.last_volume)*k;if (next-volume).abs()<0.002{volume}else{next}};if (target-bus.last_volume).abs()>0.0001 || (target==0. && bus.last_volume!=0.){if let Some(s)=sink.as_mut(){s.set_volume(bevy::audio::Volume::Linear(target));}if let Some(s)=spatial_sink.as_mut(){s.set_volume(bevy::audio::Volume::Linear(target));}bus.last_volume=target;}}}

#[derive(Default)] struct HudGroup<'a>{widgets:Vec<&'a forge_engine::Widget>,children:std::collections::BTreeMap<String,HudGroup<'a>>}
impl<'a> HudGroup<'a>{
 fn insert(&mut self,path:&[&str],widget:&'a forge_engine::Widget){if let Some((head,tail))=path.split_first(){self.children.entry((*head).into()).or_default().insert(tail,widget);}else{self.widgets.push(widget);}}
 fn first(&self)->Option<&'a forge_engine::Widget>{self.widgets.first().copied().or_else(||self.children.values().find_map(|c|c.first()))}
 fn draw(&self,ui:&mut egui::Ui,input:&mut HudInput){for w in &self.widgets{if w.action=="label"{ui.label(&w.text);}else{let r=ui.button(&w.text);if r.is_pointer_button_down_on(){match w.action.as_str(){"left"=>input.0[0]-=1.,"right"=>input.0[0]+=1.,"jump"=>input.0[1]=1.,_=>{}}}}}for (name,child) in &self.children{ui.collapsing(name.as_str(),|ui|child.draw(ui,input));}}
}

#[cfg(feature="lighting")]
fn gpu_scene_sync(game:Res<Game>,mut draw:forge_engine::gpu_scene::GpuDraw,mut sprites:Query<(Entity,&ObjectId,&Sprite,&Transform,&mut Visibility)>){
 if (!game.project.settings.gpu_lighting||game.project.isometric)&&draw.idle(){return;}
 let objects:std::collections::HashMap<_,_>=game.project.objects.iter().map(|o|(o.id,o)).collect();
 draw.sync(&game.project,Some(&game.root),game.sim.elapsed,sprites.iter_mut().filter_map(|(entity,id,s,t,v)|objects.get(&id.0).map(|o|(entity,*o,s,t,v))));
}

#[cfg(feature="lighting")]
fn gpu_particles_sync(game:Res<Game>,time:Res<Time>,mut draw:forge_engine::gpu_particles::ParticleDraw){draw.sync(&game.project,Some(&game.root),if game.menu{0.}else{time.delta_secs()});}

fn inventory_panel(ctx:&egui::Context,game:&mut Game){
 if game.inventory.is_none(){return;}
 egui::Area::new(egui::Id::new("inventory_toggle22")).anchor(egui::Align2::RIGHT_TOP,[-12.,12.]).show(ctx,|ui|{if ui.button("Inventory [I]").clicked(){game.inventory_open=!game.inventory_open;}if !game.inventory_open&&!game.inventory_message.is_empty(){ui.small(&game.inventory_message);}});
 if !game.inventory_open{return;}
 let mut open=game.inventory_open;let mut action=None;let mut save=false;let mut load=false;let mut use_item=None;let mut equip_item=None;let mut unequip=None;
 egui::Window::new("Inventory").open(&mut open).show(ctx,|ui|{
  ui.label("E: collect nearby · drag or select two slots to move/merge");
  let inv=game.inventory.as_ref().unwrap();
  egui::Grid::new("forge_inventory_slots22").spacing([5.,5.]).show(ui,|ui|{for (i,slot) in inv.slots.iter().enumerate(){let label=slot.as_ref().map(|s|format!("{} ×{}",s.item,s.count)).unwrap_or_else(||format!("Slot {}",i+1));let response=ui.add_sized([100.,46.],egui::Button::new(label).selected(game.inventory_selected==Some(i)).sense(egui::Sense::click_and_drag()));if slot.is_some(){response.dnd_set_drag_payload(i);}if let Some(from)=response.dnd_release_payload::<usize>(){action=Some((*from,i));game.inventory_selected=None;}else if response.clicked(){if let Some(from)=game.inventory_selected.take(){if from!=i{action=Some((from,i));}}else if slot.is_some(){game.inventory_selected=Some(i);}}if i%4==3{ui.end_row();}}});
  if let Some(i)=game.inventory_selected{if let Some(item)=inv.slots.get(i).and_then(Option::as_ref){if let Some(def)=game.project.settings.item_catalog.get(&item.item){ui.label(format!("{} · heal {:.1} · damage +{:.1}",item.item,def.heal,def.damage_bonus));ui.horizontal(|ui|{if ui.add_enabled(def.heal>0.||def.variable_delta!=0.,egui::Button::new("Use")).clicked(){use_item=Some(i);}if ui.add_enabled(!def.equip_slot.is_empty(),egui::Button::new("Equip")).clicked(){equip_item=Some(i);}});}}}
  for (slot,item) in &inv.equipped{ui.horizontal(|ui|{ui.label(format!("{slot}: {}",item.item));if ui.small_button("Unequip").clicked(){unequip=Some(slot.clone());}});}
  ui.label(format!("Equipment damage bonus: {:.1}",inv.damage_bonus(&game.project.settings.item_catalog)));
  ui.horizontal(|ui|{save=ui.button("Save inventory").clicked();load=ui.button("Load inventory").clicked();});ui.label(&game.inventory_message);
 });game.inventory_open=open;
 if let Some((a,b))=action{if let Some(inv)=game.inventory.as_mut(){inv.move_slot(a,b);}}
 if let Some(i)=use_item{if let Some(inv)=game.inventory.as_mut(){game.inventory_message=match inv.use_item(i,&mut game.project){Ok(s)|Err(s)=>s};if inv.slots.get(i).is_none_or(Option::is_none){game.inventory_selected=None;}}}
 if let Some(i)=equip_item{if let Some(inv)=game.inventory.as_mut(){game.inventory_message=match inv.equip(i,&game.project.settings.item_catalog){Ok(s)|Err(s)=>s};if inv.slots.get(i).is_none_or(Option::is_none){game.inventory_selected=None;}}}
 if let Some(slot)=unequip{if let Some(inv)=game.inventory.as_mut(){game.inventory_message=match inv.unequip(&slot){Ok(s)|Err(s)=>s};}}
 let path=game.root.join("inventory-save.json");
 if save{game.inventory_message=match game.inventory.as_ref().unwrap().save(&path){Ok(())=>"Inventory saved".into(),Err(e)=>e};}
 if load{match forge_engine::Inventory::load(&path){Ok(inv)=>{if inv.slots.len()!=game.inventory.as_ref().unwrap().slots.len()||!inv.equipment_valid(&game.project.settings.item_catalog){game.inventory_message="Save slot count differs".into();}else{let original=game.original.objects.iter().filter(|o|o.pro.pickup.is_some()&&!inv.collected.contains(&o.id)).cloned().collect::<Vec<_>>();inv.remove_collected(&mut game.project);for o in original{if !game.project.objects.iter().any(|x|x.id==o.id){game.project.objects.push(o);}}game.inventory=Some(inv);game.inventory_selected=None;game.inventory_message="Inventory loaded".into();}},Err(e)=>game.inventory_message=e}}
}

fn checkpoint_entry(game:&Game)->String{game.entry.file_name().unwrap_or_default().to_string_lossy().into_owned()}
fn save_checkpoint(game:&Game)->Result<(),String>{let c=forge_engine::save_game::Checkpoint{version:1,entry:checkpoint_entry(game),level:game.level,project:game.project.clone(),inventory:game.inventory.clone(),demo:game.demo.clone(),elapsed:game.sim.elapsed,finished:game.finished};c.save(&game.entry.with_extension("checkpoint.json"))}
fn load_checkpoint(game:&mut Game)->Result<(),String>{let c=forge_engine::save_game::Checkpoint::load(&game.entry.with_extension("checkpoint.json"),&checkpoint_entry(game))?;if c.level>1&&!game.campaign{return Err("Checkpoint requires campaign".into());}let path=if c.level==1{game.entry.clone()}else{game.root.join(format!("level{}.forge.json",c.level))};let original=Project::load(&path)?;forge_engine::modules::validate(&original)?;if original.name!=c.project.name||original.settings.inventory.is_some()!=c.inventory.is_some()||c.inventory.as_ref().zip(original.settings.inventory.as_ref()).is_some_and(|(a,b)|a.slots.len()!=b.slots.len())||c.demo.is_some()!=(forge_engine::DemoSession::total(&original)>0){return Err("Checkpoint scene differs from source".into());}game.project=c.project;game.original=original;game.inventory=c.inventory;game.demo=c.demo;game.level=c.level;game.finished=c.finished;game.sim=Simulation::default();game.sim.elapsed=c.elapsed;game.menu=false;game.inventory_open=false;game.inventory_selected=None;#[cfg(feature="audio")] {game.audio_revision=game.audio_revision.wrapping_add(1);}Ok(())}
fn checkpoint_panel(ctx:&egui::Context,game:&mut Game){if !game.menu{return;}let mut save=false;let mut load=false;egui::Window::new("Game checkpoint").show(ctx,|ui|{ui.horizontal(|ui|{save=ui.button("Save game [F5]").clicked();load=ui.button("Load game [F9]").clicked();});ui.label(&game.inventory_message);ui.small("Restores scene and progress; physics and Lua VM restart.");});if save{game.inventory_message=match save_checkpoint(game){Ok(())=>"Checkpoint saved".into(),Err(e)=>e};}if load{game.inventory_message=match load_checkpoint(game){Ok(())=>"Checkpoint loaded".into(),Err(e)=>e};}}
